}

Method.Source:
[
    DataMemberAttribute('fromDate')
]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[
    DataMemberAttribute('toDate')
]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

[
    DataMemberAttribute("rebateDealRecId")
]
public TAMRebateDealId parmRebateDealRecId(TAMRebateDealId _rebateDealRecId = rebateDealRecId)
{
    rebateDealRecId = _rebateDealRecId;
    return rebateDealRecId;
}
